<!doctype html><html><head><meta charset="utf-8"><title>{{ $borrowing->borrowing_code }} Receipt</title><style>body{font-family:Arial,sans-serif;color:#111827;margin:32px}.head{display:flex;justify-content:space-between;border-bottom:2px solid #166534;padding-bottom:16px}.title{color:#166534}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{border:1px solid #d1d5db;padding:10px;text-align:left}th{background:#f3f4f6}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:24px}.label{font-size:11px;text-transform:uppercase;color:#6b7280}.no-print{margin-bottom:20px}@media print{.no-print{display:none}body{margin:0}}</style></head><body><button class="no-print" onclick="window.print()">Print Receipt</button><div class="head"><div><h1 class="title">UCC LabTech</h1><div>Borrowing Acknowledgment Receipt</div></div><div><strong>{{ $borrowing->borrowing_code }}</strong><br>{{ strtoupper($borrowing->status) }}</div></div><div class="grid"><div><div class="label">Borrower</div><strong>{{ $borrowing->borrower_name }}</strong><div>{{ $borrowing->borrower_identifier ?: $borrowing->borrower_email }}</div></div><div><div class="label">Purpose</div>{{ $borrowing->purpose }}</div><div><div class="label">Borrow Schedule</div>{{ $borrowing->borrow_at?->format('M d, Y h:i A') }}</div><div><div class="label">Expected Return</div>{{ $borrowing->expected_return_at?->format('M d, Y h:i A') }}</div></div><table><thead><tr><th>Equipment</th><th>Asset Number</th><th>Condition Out</th><th>Condition In</th></tr></thead><tbody>@foreach($borrowing->items as $line)<tr><td>{{ $line->itemUnit->item->name }}</td><td>{{ $line->itemUnit->asset_number }}</td><td>{{ $line->condition_out ?: '—' }}</td><td>{{ $line->condition_in ?: '—' }}</td></tr>@endforeach</tbody></table><div style="margin-top:60px;display:flex;justify-content:space-between"><div>_________________________<br>Borrower Signature</div><div>_________________________<br>Lab Technician</div></div></body></html>